SELECT DISTINCT OH.ORDER_ID, OH.STATUS_ID, OH.ORDER_TYPE_ID, OH.PRODUCT_STORE_ID, OH.SALES_CHANNEL_ENUM_ID, OH.PRIORITY, OH.ORDER_DATE, SG.DELIVERY_DAYS, SG.ITEM_COUNT FROM ORDER_HEADER OH LEFT OUTER JOIN ORDER_IDENTIFICATION OID ON OH.ORDER_ID = OID.ORDER_ID AND (((OID.FROM_DATE  IS NULL OR OID.FROM_DATE <= '2026-09-10 22:13:51.891000') AND (OID.THRU_DATE  IS NULL OR OID.THRU_DATE > '2026-09-10 22:13:51.891000')) AND OID.ORDER_IDENTIFICATION_TYPE_ID = 'NETSUITE_ORDER_ID') INNER JOIN  LATERAL (SELECT MIN(CSM.DELIVERY_DAYS) AS DELIVERY_DAYS, COUNT(OI.ORDER_ITEM_SEQ_ID) AS ITEM_COUNT FROM ORDER_ITEM_SHIP_GROUP OISG INNER JOIN ORDER_ITEM OI ON OISG.ORDER_ID = OI.ORDER_ID AND OISG.SHIP_GROUP_SEQ_ID = OI.SHIP_GROUP_SEQ_ID LEFT OUTER JOIN CARRIER_SHIPMENT_METHOD CSM ON OISG.SHIPMENT_METHOD_TYPE_ID = CSM.SHIPMENT_METHOD_TYPE_ID AND OISG.CARRIER_PARTY_ID = CSM.PARTY_ID AND OISG.CARRIER_ROLE_TYPE_ID = CSM.ROLE_TYPE_ID WHERE OH.ORDER_ID = OISG.ORDER_ID) SG ON 1=1 WHERE (OH.PRODUCT_STORE_ID = 'STORE' AND OH.ORDER_DATE > '2026-08-15T00:00:00' AND OH.ORDER_TYPE_ID = 'SALES_ORDER' AND OID.ORDER_ID IS NULL AND SG.ITEM_COUNT > '0') ORDER BY OH.ORDER_DATE ASC